SELECT * FROM ( SELECT bbp.payee_date as payeeDate, be.employee_name as payeeUser, bb.bill_date as billDate, bo.abbreviation, emp.employee_name as employeeName, bb.bill_num as billNum, bbpd.principal_amount as amount, bbpd.card_num as remark, bp.name as patientName, null as discountUser, CASE WHEN bbpd.account_item_id=23 then '本次免单支付' WHEN bbpd.account_item_id=26 then '艾维员工免单' end as discountFree FROM base_bill_pay_detail bbpd LEFT JOIN base_bill bb ON bb.bill_id=bbpd.bill_id LEFT JOIN base_bill_pay bbp ON bbp.bill_pay_id=bbpd.bill_pay_id LEFT JOIN base_employee be ON be.user_id=bbp.payee_user_id LEFT JOIN base_treatment_process btp ON btp.treatment_id=bb.treatment_id LEFT JOIN base_employee emp ON emp.user_id=btp.registered_dentist_id LEFT JOIN base_organization bo ON bo.org_id=bb.org_id LEFT JOIN base_patient bp ON bp.patient_id=bb.patient_id
and bbpd.account_item_id in (23,26)
bbpd.account_item_id = #{query.accountType}
and bb.org_id in
#{item}
and DATE_FORMAT(bbp.payee_date,'%Y-%m-%d') between #{query.startDate} and #{query.endDate}
and btp.registered_dentist_id in
#{item}
UNION SELECT bbp.payee_date as payeeDate, be.employee_name as payeeUser, bb.bill_date as billDate, bo.abbreviation, emp.employee_name as employeeName, bb.bill_num as billNum, bbf.principal_amount as amount, bbf.remark, bp.name as patientName, bep.employee_name as discountUser, '授权折扣' as discountFree FROM ( select order_id as bill_id,sum(benefit_amount) as principal_amount, remark, authorized_id, patient_id from base_benefit
choice_benefit_type=1
and order_id = -1 and org_id = -1
group by order_id,remark,authorized_id,patient_id ) bbf LEFT JOIN base_bill bb ON bb.bill_id=bbf.bill_id LEFT JOIN base_bill_pay bbp ON (bbp.bill_id = bbf.bill_id AND TIMESTAMPDIFF(SECOND,bb.privilege_date, bbp.payee_date)<=5) LEFT JOIN base_employee be ON be.user_id=bbp.payee_user_id LEFT JOIN base_treatment_process btp ON btp.treatment_id=bb.treatment_id LEFT JOIN base_employee emp ON emp.user_id=btp.registered_dentist_id LEFT JOIN base_employee bep ON bep.user_id=bbf.authorized_id LEFT JOIN base_organization bo ON bo.org_id=bb.org_id LEFT JOIN base_patient bp ON bp.patient_id=bbf.patient_id
and bb.org_id in
#{item}
and DATE_FORMAT(bbp.payee_date,'%Y-%m-%d') between #{query.startDate} and #{query.endDate}
and btp.registered_dentist_id in
#{item}
) t order by t.payeeDate desc,t.billNum desc
